class TextExtractor(HTMLParser):
    def __init__(self):
        super().__init__()
        self.text = []
        self.skip = 0
    def handle_starttag(self, tag, attrs):
        attrs_dict = dict(attrs)
        if tag in ['script','style']:
            self.skip += 1
        if tag in ['br','p','div','section','li']:
            self.text.append('\n')
        if tag == 'a' and 'footnote-reference' in attrs_dict.get('class',''):
            return
        if tag == 'span' and 'pre' in attrs_dict.get('class',''):
            self.text.append('`')
    def handle_endtag(self, tag):
        if tag in ['script','style']:
            self.skip -= 1
        if tag == 'span' and self.text and self.text[-1] == '`':
            self.text.append('`')
    def handle_data(self, data):
        if self.skip == 0:
            self.text.append(data)

