"""Click an element in the macOS AX tree by role and text substring."""
import sys
import subprocess
import time

try:
    import ApplicationServices as AX
    from AppKit import NSWorkspace
except ImportError:
    print("ERROR: pyobjc not installed.", file=sys.stderr)
    sys.exit(1)

target_app = sys.argv[1] if len(sys.argv) > 1 else "Google Chrome"
role_filter = sys.argv[2] if len(sys.argv) > 2 else "AXLink"
text_filter = sys.argv[3] if len(sys.argv) > 3 else ""

subprocess.run(
    ["osascript", "-e", f'tell application "{target_app}" to activate'],
    capture_output=True, timeout=5,
)
time.sleep(0.5)

def find_app(name):
    apps = NSWorkspace.sharedWorkspace().runningApplications()
    name_lower = name.lower()
    for app in apps:
        if name_lower in (app.localizedName() or "").lower():
            return app
    return None

app = find_app(target_app)
if not app:
    print(f"ERROR: app '{target_app}' not running", file=sys.stderr)
    sys.exit(1)

pid = app.processIdentifier()
ax_app = AX.AXUIElementCreateApplication(pid)
try:
    AX.AXUIElementSetAttributeValue(ax_app, "AXManualAccessibility", True)
    AX.AXUIElementSetAttributeValue(ax_app, "AXEnhancedUserInterface", True)
    time.sleep(0.4)
except Exception:
    pass

err, windows = AX.AXUIElementCopyAttributeValue(ax_app, "AXWindows", None)
if err != 0 or not windows:
    print(f"ERROR: no window", file=sys.stderr)
    sys.exit(1)

err, focused = AX.AXUIElementCopyAttributeValue(ax_app, "AXFocusedWindow", None)
window = focused if (err == 0 and focused) else windows[0]

def walk(element, depth=0, max_depth=25):
    if depth > max_depth:
        return None
    err, role = AX.AXUIElementCopyAttributeValue(element, "AXRole", None)
    role_str = str(role) if role else ""
    if role_str == role_filter:
        for attr in ("AXTitle", "AXValue", "AXDescription"):
            err, val = AX.AXUIElementCopyAttributeValue(element, attr, None)
            if err == 0 and val and text_filter in str(val):
                return element
    err, children = AX.AXUIElementCopyAttributeValue(element, "AXChildren", None)
    if children:
        for child in children[:60]:
            found = walk(child, depth + 1, max_depth)
            if found:
                return found
    return None

print(f"Looking for {role_filter} containing '{text_filter}'...")
result = walk(window)
if result:
    print("Found element, clicking...")
    err = AX.AXUIElementPerformAction(result, "AXPress")
    if err == 0:
        print("Clicked successfully.")
    else:
        print(f"AXPress failed with error {err}", file=sys.stderr)
        sys.exit(1)
else:
    print("Element not found.", file=sys.stderr)
    sys.exit(1)
"}

