"""
Click a UI element in the frontmost window of a target app by its AX label.
Usage: click_ax.py <app name> <role> <label>
e.g.:  click_ax.py "Google Chrome" AXButton Keywords
"""
import sys
import time
import subprocess

def main():
    if len(sys.argv) < 4:
        print("Usage: click_ax.py <app name> <role> <label>", file=sys.stderr)
        sys.exit(2)

    target_app = sys.argv[1]
    target_role = sys.argv[2]
    target_label = sys.argv[3]

    try:
        import ApplicationServices as AX
        from AppKit import NSWorkspace
    except ImportError:
        print("ERROR: pyobjc not installed", file=sys.stderr)
        sys.exit(1)

    # Activate
    subprocess.run(
        ["osascript", "-e", f'tell application "{target_app}" to activate'],
        capture_output=True, timeout=5,
    )
    time.sleep(0.5)

    # Find app
    apps = NSWorkspace.sharedWorkspace().runningApplications()
    app = None
    for a in apps:
        if target_app.lower() in (a.localizedName() or "").lower():
            app = a
            break
    if not app:
        print(f"ERROR: app '{target_app}' not running", file=sys.stderr)
        sys.exit(1)

    pid = app.processIdentifier()
    ax_app = AX.AXUIElementCreateApplication(pid)

    try:
        AX.AXUIElementSetAttributeValue(ax_app, "AXManualAccessibility", True)
        AX.AXUIElementSetAttributeValue(ax_app, "AXEnhancedUserInterface", True)
        time.sleep(0.4)
    except Exception:
        pass

    err, windows = AX.AXUIElementCopyAttributeValue(ax_app, "AXWindows", None)
    if err != 0 or not windows:
        print(f"ERROR: could not read windows", file=sys.stderr)
        sys.exit(1)

    err, focused = AX.AXUIElementCopyAttributeValue(ax_app, "AXFocusedWindow", None)
    window = focused if (err == 0 and focused) else windows[0]

    def find_and_click(element, depth=0, max_depth=25):
        if depth > max_depth:
            return False

        err, role = AX.AXUIElementCopyAttributeValue(element, "AXRole", None)
        if err != 0:
            role = ""
        else:
            role = str(role) if role else ""

        text = ""
        for attr in ("AXTitle", "AXValue", "AXDescription"):
            err, val = AX.AXUIElementCopyAttributeValue(element, attr, None)
            if err == 0 and val and str(val).strip():
                text = str(val).strip()
                break

        if role == target_role and text == target_label:
            print(f"Found and clicking: {role}: {text}")
            err = AX.AXUIElementPerformAction(element, "AXPress")
            if err != 0:
                # Try AXClick if AXPress fails
                try:
                    err = AX.AXUIElementPerformAction(element, "AXClick")
                except:
                    pass
            return True

        err, children = AX.AXUIElementCopyAttributeValue(element, "AXChildren", None)
        if children:
            for child in children:
                if find_and_click(child, depth + 1, max_depth):
                    return True
        return False

    if find_and_click(window):
        print("Click performed successfully")
    else:
        print(f"ERROR: Could not find {target_role} with label '{target_label}'", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
"}

